def close(x, ref, rtol: float = 1e-8, atol: float = 1e-10) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def csort(z):
    return sorted(z, key=lambda c: (round(c.real, 8), round(c.imag, 8)))

n = 30
d0 = np.array([float(i + 1) for i in range(n)])
T = sp.diags_array([d0 + 2, -np.ones(n - 1), -np.ones(n - 1)], offsets=[0, 1, -1]).tocsr()
N = sp.diags_array([d0 + 2, -2 * np.ones(n - 1), np.ones(n - 1), 0.5 * np.ones(n - 3)],
                   offsets=[0, 1, -1, 3]).tocsr()
b = np.array([math.sin(i + 1.0) for i in range(n)])

@test
def test_krylov():
    x, info = sl.cg(T, b, rtol=1e-10)
    assert info == 0 and close(x, x_cg, 1e-12, 1e-13)
    x, info = sl.bicgstab(N, b, rtol=1e-10)
    assert info == 0 and close(x, x_bicgstab, 1e-12, 1e-13)
    x, info = sl.gmres(N, b, rtol=1e-10)
    assert info == 0 and close(x, x_gmres, 1e-12, 1e-13)
    x, info = sl.gmres(N, b, rtol=1e-10, restart=5)
    assert info == 0 and close(x, x_gmres5, 1e-11, 1e-12)
    x, info = sl.minres(T, b, rtol=1e-10)
    assert info == 0 and close(x, x_minres, 1e-12, 1e-13)
    x, info = sl.cgs(N, b, rtol=1e-10)
    assert info == 0 and close(x, x_cgs, 1e-11, 1e-12)
    x, info = sl.bicg(N, b, rtol=1e-10)
    assert info == 0 and close(x, x_bicg, 1e-11, 1e-12)
    # preconditioned CG (Jacobi) with LinearOperator
    dg = T.diagonal()
    Mop = sl.LinearOperator((n, n), lambda v: v / dg, dtype=float)
    x, info = sl.cg(T, b, rtol=1e-12, M=Mop)
    assert info == 0 and close(T @ x, b, 1e-9, 1e-10)
    Aop = sl.aslinearoperator(N)
    x, info = sl.gmres(Aop, b, rtol=1e-10)
    assert info == 0 and close(x, x_gmres, 1e-12, 1e-13)
test_krylov()

@test
def test_lsq():
    # The iterations are those of scipy (bit-identical under CPython); in
    # Typhon norm/dot rounding differs slightly and this bidiagonalization
    # amplifies it (lsmr stops at its iteration limit), hence ~1e-6.
    res = sl.lsqr(N, b, atol=1e-12, btol=1e-12)
    assert close(res[0], x_lsqr, 1e-5, 1e-6) and abs(res[2] - lsqr_itn) <= 2
    res2 = sl.lsmr(N, b, atol=1e-12, btol=1e-12)
    assert close(res2[0], x_lsmr, 1e-5, 1e-6) and abs(res2[2] - lsmr_itn) <= 2
test_lsq()

@test
def test_direct():
    assert close(sl.spsolve(N, b), x_spsolve, 1e-12, 1e-13)
    lu = sl.splu(sp.csc_array(N))
    assert close(lu.solve(b), splu_x, 1e-12, 1e-13)
    assert close(lu.solve(b, trans='T'), splu_xT, 1e-12, 1e-13)
    assert close(sl.inv(sp.csc_array(np.array([[4., 1.], [2., 3.]]))).toarray(), inv_d)
    Lt = sp.csr_array(np.array([[2., 0., 0.], [1., 3., 0.], [4., 5., 6.]]))
    assert close(sl.spsolve_triangular(Lt, np.array([1., 2., 3.])), tri_x)
    # pivoting is required here (zero leading diagonal)
    P = sp.csc_array(np.array([[0., 2., 1.], [1., 1., 0.], [3., 0., 1.]]))
    xp = sl.spsolve(P, np.array([1., 2., 3.]))
    assert close(P @ xp, [1., 2., 3.], 1e-12, 1e-13)
    Bm = np.array([[1., 0.], [0., 1.], [2., 2.]])
    Xm = sl.spsolve(P, Bm)
    assert close(P @ Xm, Bm, 1e-12, 1e-13)
    Cz = sp.csc_array(np.array([[2 + 1j, 1j], [1 + 0j, 3 + 0j]]))
    xc = sl.spsolve(Cz, np.array([1 + 0j, 2j]))
    assert close(Cz @ xc, [1 + 0j, 2j], 1e-12, 1e-13)
test_direct()

@test
def test_eigen():
    for w, ref in [("LM", eigsh_LM), ("SM", eigsh_SM), ("LA", eigsh_LA), ("SA", eigsh_SA), ("BE", eigsh_BE)]:
        ev, V = sl.eigsh(T, k=4, which=w)
        assert close(ev, ref, 1e-9, 1e-9)
        assert close(T @ V, V * ev, 1e-7, 1e-7)
    assert close(sl.eigsh(T, k=3, sigma=10.2)[0], eigsh_sigma, 1e-9, 1e-9)
    E = sp.diags_array([d0, -2 * np.ones(n - 1), np.ones(n - 1)], offsets=[0, 1, -1]).tocsr()
    ev2, V2 = sl.eigs(E, k=4, which='LM')
    assert close(csort(ev2), eigs_LM, 1e-8, 1e-8)
    assert close(E @ V2, V2 * ev2, 1e-6, 1e-6)
    ev3, _ = sl.eigs(E, k=3, which='SR')
    assert close(csort(ev3), eigs_SR, 1e-8, 1e-8)
    R = sp.csr_array(np.array([[(i * 7 + j * 3) % 11 - 5.0 if (i + j) % 3 else 0. for j in range(12)]
                               for i in range(20)]))
    u, s, vh = sl.svds(R, k=3)
    assert close(s, svds_s, 1e-9, 1e-9)
    assert close(u * s @ vh, (u * s) @ vh)
    assert close(R @ vh.T, u * s, 1e-7, 1e-7)
    ew = sl.eigsh(T, k=2, which='LA', return_eigenvectors=False)
    assert close(ew, eigsh_LA[2:], 1e-9, 1e-9)
test_eigen()

@test
def test_misc():
    assert close(sl.norm(N), norm_fro) and close(sl.norm(N, 1), norm_1)
    assert close(sl.norm(N, np.inf), norm_inf)
    assert close(sl.norm(N, axis=0)[:5], norm_ax0)
    assert close(sl.expm_multiply(T * -0.1, b), expm_mul, 1e-12, 1e-13)
    L = sl.LinearOperator((2, 2), lambda v: np.array([2 * v[0] + v[1], 3 * v[1]]),
                          rmatvec=lambda v: np.array([2 * v[0], v[0] + 3 * v[1]]), dtype=float)
    assert close(L @ np.array([1., 1.]), [3., 3.]) and close(L.H @ np.array([1., 1.]), [2., 4.])
    assert close((L * 2.0 + L).matvec(np.array([1., 0.])), [6., 0.])
    assert close(L.matmat(np.eye(2)), [[2., 1.], [0., 3.]])
    assert close(sl.onenormest(N), norm_1)
test_misc()
